<script setup lang="ts">
/**
 * Add hardware: five questions, one per step, each beside a pose of the Rhino Studio rhino
 * (src/assets/wizard/, generated by scripts/wizard_poses.py; this wizard is the only place it appears).
 *
 *   What is it → Wiring → For which tools → Follows → Shows → Check
 *
 * The Portal (Tool Manager 1.9) owns every rule: the catalog says what exists and what it needs, the pin
 * picker offers only free pins that can do the job, and the Check step is the Portal's own preview of the
 * Klipper text. Save writes custom_tools.cfg, live after the next Klipper restart. Nothing here switches
 * anything on or moves the machine. "Second control board" runs a shorter flow that adds [mcu name].
 *
 * /assets/hardware/<name>/edit opens a saved device with its answers filled in (draftFrom); its kind is fixed,
 * its own pins are offered again, and Save replaces it. The Portal refuses a change that would break a job hook.
 */
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import RsButton from '@/components/RsButton.vue'
import RsPanel from '@/components/RsPanel.vue'
import RestartBanner from '@/toolmgr/RestartBanner.vue'
import {
  STEP_HELP, STEP_LABEL, STEP_POSE, WIRES_HELP, fanPinHelp, WIRING_KEYS, WIZ_STEPS, asksSensorType, checkStep, draftFrom, newDraft, payload, pinLabel, pinText, pinsShown,
  settingLabel, settingShown, type BoardsState, type DevicePreview, type Draft, type HwCatalog, type HwDevice, type HwSetting, type PinChoice, type SavedDevice, type WizStep,
} from '@/hardware/wizard'
import { useToolMgrStore } from '@/stores/toolmgr'
import '@/toolmgr/forms.css'

const POSES = import.meta.glob('@/assets/wizard/rhino-*.svg', { eager: true, query: '?url', import: 'default' }) as Record<string, string>
const pose = (p: string) => Object.entries(POSES).find(([k]) => k.endsWith(`rhino-${p}.svg`))?.[1] ?? ''

const props = defineProps<{ name?: string }>()
const router = useRouter()
const tm = useToolMgrStore()
const editing = computed(() => !!props.name)
onBeforeUnmount(tm.use())

const cat = ref<HwCatalog | null>(null)
const boards = ref<BoardsState | null>(null)
const takenNames = ref<string[]>([])
const error = ref<string | null>(null)
const dev = ref<HwDevice | null>(null)
const d = ref<Draft | null>(null)
const at = ref(0)
const saved = ref<string | null>(null)

async function load() {
  const c = tm.client()
  const [catalog, b, devs] = await Promise.all([c.hwCatalog(), c.hwBoards(), c.hwDevices()])
  cat.value = catalog
  boards.value = b
  takenNames.value = [...devs.devices.map((x) => x.name), ...(tm.pins?.hardware ?? []).map((h) => h.name), ...b.boards.map((x) => x.name)]
    .filter((n) => n !== props.name)
  if (props.name) {
    const sv = devs.devices.find((x) => x.name === props.name) as unknown as SavedDevice | undefined
    const kind = sv && catalog.groups.flatMap((g) => g.devices).find((x) => x.id === sv.device)
    if (!sv || !kind) throw new Error(`No hardware called ${props.name} was added with the wizard.`)
    dev.value = kind
    d.value = draftFrom(sv, kind, catalog.follows_built ?? [])
  }
}
onMounted(() => load().catch((e) => (error.value = (e as Error).message)))
// The router keeps this page when only the device in the address changes (Edit fan -> Edit lid, or Add -> Edit)
watch(() => props.name, () => another())

const isBoard = computed(() => dev.value?.id === 'board')
const steps = computed<WizStep[]>(() => (isBoard.value ? ['What', 'Wiring', 'Check'] : WIZ_STEPS))
const step = computed(() => steps.value[Math.min(at.value, steps.value.length - 1)]!)
const built = computed(() => cat.value?.follows_built ?? [])

function pick(x: HwDevice) {
  if (x.status !== 'ready' && x.id !== 'board') return
  if (x.writer === 'form') return
  dev.value = x
  d.value = newDraft(x, built.value)
  board.name = ''
  error.value = null
}

// ---------------------------------------------------------------- wiring: the Portal's pin picker
const choices = ref<Record<string, PinChoice[]>>({})
const typed = reactive<Record<string, boolean>>({})
const typedCheck = ref<Record<string, PinChoice & { ok: boolean }>>({})
async function loadPins() {
  if (!dev.value || !d.value || isBoard.value) return
  const kinds = [...new Set(pinsShown(dev.value, d.value).map((p) => p[1]))]
  const out: Record<string, PinChoice[]> = {}
  for (const k of kinds) {
    const sensor = k === 'digital_in' && d.value.sensor_type ? d.value.sensor_type : undefined
    out[k] = (await tm.client().hwPins(k, sensor, d.value.original)).pins
  }
  choices.value = out
}
watch([step, () => d.value?.sensor_type, () => d.value?.settings.source, () => d.value?.settings.wires], () => {
  if (step.value === 'Wiring') loadPins().catch((e) => (error.value = (e as Error).message))
})
/** A 4-wire fan's power pin is a fan / heater header; its speed input can be either (a header pulls it to ground, inverted). */
const fan4 = computed(() => String(d.value?.settings.wires) === '4')
function choicesFor(slot: string, kind: string): PinChoice[] {
  const all = choices.value[kind] ?? []
  if (fan4.value && slot === 'power') return all.filter((p) => p.mosfet)
  return all
}
const slotLabel = (slot: string) => (fan4.value && slot === 'pin' ? 'Speed input (blue wire)' : slot === 'tach' ? 'Speed signal (yellow wire)' : pinLabel(slot))
const pinHelp = (slot: string, kind: string) => (asksWires.value ? fanPinHelp(slot, String(d.value?.settings.wires)) : null) ?? cat.value?.pin_kinds[kind]?.help
/** A 4-wire fan's speed input is meant to be a logic pin: the "logic pin, not a load" note doesn't apply. */
const pinWarnings = (slot: string, kind: string) => {
  const ws = (chosen(slot, kind)?.warnings ?? []).filter((w) => !(fan4.value && slot === 'pin' && (w.includes('3.3 V logic pin') || w.includes('switches supply voltage'))))
  const c = chosen(slot, kind)
  if (fan4.value && slot === 'pin' && c?.mosfet) {
    ws.push(`${c.header || c.pin} is a fan header: connect only its − pin to the blue wire, leave + unconnected, and tick "The speed input is inverted" below (the header pulls the signal to ground).`)
  }
  return ws
}
const chosen = (slot: string, kind: string) => (choices.value[kind] ?? []).find((p) => p.pin === d.value?.pins[slot]) ?? typedCheck.value[slot] ?? null
async function checkTyped(slot: string, kind: string) {
  if (!d.value?.pins[slot]) return
  try {
    typedCheck.value[slot] = await tm.client().checkPin({ pin: d.value.pins[slot]!, kind, sensor: kind === 'digital_in' ? d.value.sensor_type || undefined : undefined, isolated: d.value.isolated })
    error.value = null
  } catch (e) {
    delete typedCheck.value[slot]
    error.value = (e as Error).message
  }
}
const needsIsolation = computed(() => !!dev.value && !!d.value && pinsShown(dev.value, d.value).some(([slot, kind]) => kind === 'digital_in' && cat.value?.sensor_types[d.value!.sensor_type]?.refuse_direct && d.value!.pins[slot]))
const sensorTypes = computed(() => Object.entries(cat.value?.sensor_types ?? {}).filter(([, s]) => s.pin_kind === 'digital_in'))
const wiringSettings = computed(() => (dev.value?.settings ?? []).filter((s) => WIRING_KEYS.has(s.key) && s.key !== 'wires' && settingShown(s.key, d.value!)))
const asksWires = computed(() => (dev.value?.settings ?? []).some((s) => s.key === 'wires'))
const behaviourSettings = computed(() => (dev.value?.settings ?? []).filter((s) => !WIRING_KEYS.has(s.key)))

// ---------------------------------------------------------------- for which tools
const CATS: [string, string][] = [['additive', 'Additive'], ['subtractive', 'Subtractive'], ['passive', 'Passive']]
function toggle(list: string[], v: string, on: boolean) {
  const i = list.indexOf(v)
  if (on && i < 0) list.push(v)
  if (!on && i >= 0) list.splice(i, 1)
}

// ---------------------------------------------------------------- second board
const board = reactive({ name: '', preset: 'ebb_v1_2', link: 'usb' as 'usb' | 'can', serial: '', canbus_uuid: '' })
const boardBody = () => ({ name: board.name.trim().toLowerCase(), preset: board.preset, link: board.link, ...(board.link === 'usb' ? { serial: board.serial } : { canbus_uuid: board.canbus_uuid.trim() }) })

// ---------------------------------------------------------------- check and save
const preview = ref<DevicePreview | { text: string; warnings: string[] } | null>(null)
const checking = ref(false)
const saving = ref(false)
watch(step, async (s) => {
  preview.value = null
  if (s !== 'Check' || !dev.value || !d.value) return
  checking.value = true
  try {
    if (isBoard.value) {
      const r = await tm.client().previewBoard(boardBody())
      preview.value = { text: r.cfg, warnings: r.warnings }
    } else preview.value = await tm.client().previewDevice(payload(d.value, dev.value))
  } catch (e) {
    error.value = (e as Error).message
  } finally {
    checking.value = false
  }
})

function stepError(): string | null {
  if (isBoard.value) {
    if (step.value === 'What' && !/^[a-z][a-z0-9_]{1,15}$/.test(board.name.trim().toLowerCase())) return 'Board name: lower-case letters, digits and _, 2 to 16 characters.'
    if (step.value === 'What' && takenNames.value.includes(board.name.trim().toLowerCase())) return `${board.name} is already used.`
    if (step.value === 'Wiring' && board.link === 'usb' && !board.serial) return 'Choose the board\'s USB connection.'
    if (step.value === 'Wiring' && board.link === 'can' && !/^[0-9a-fA-F]{12}$/.test(board.canbus_uuid.trim())) return 'CAN bus UUID: 12 hex digits.'
    return null
  }
  const e = checkStep(step.value, dev.value, d.value, takenNames.value, built.value)
  if (!e && step.value === 'Wiring' && needsIsolation.value && !d.value!.isolated) return 'Confirm an optocoupler or divider is fitted between the sensor and the pin.'
  return e
}
async function next() {
  error.value = null
  if (step.value !== 'Check') {
    const e = stepError()
    if (e) return (error.value = e)
    at.value++
    return
  }
  if (saving.value || !preview.value) return
  saving.value = true
  try {
    const r = isBoard.value ? await tm.client().saveBoard(boardBody()) : await tm.client().saveDevice(payload(d.value!, dev.value!))
    saved.value = String(r.name ?? d.value?.name ?? board.name)
    await tm.changed()
  } catch (e) {
    error.value = (e as Error).message
  } finally {
    saving.value = false
  }
}
function back() {
  error.value = null
  at.value = Math.max(0, at.value - 1)
}
function goTo(i: number) {
  if (i < at.value) {
    error.value = null
    at.value = i
  }
}
async function another() {
  saved.value = null
  dev.value = null
  d.value = null
  at.value = 0
  await load().catch((e) => (error.value = (e as Error).message))
}
const fmt = (s: HwSetting) => (s.kind === 'num' && s.min != null ? `${s.min} to ${s.max}` : '')
</script>

<template>
  <div class="view">
    <RouterLink to="/assets/hardware" class="back">‹ System hardware</RouterLink>
    <div class="view-head">
      <h1>{{ editing ? `Edit ${name}` : 'Add hardware' }}</h1>
      <p v-if="editing">Its answers are filled in. Change what you need; the Portal checks the result against your whole Klipper config and replaces it. It's live after the next Klipper restart.</p>
      <p v-else>Five questions. The Portal offers only pins that can do the job, checks the result against your whole Klipper config, and writes it. It's live after the next Klipper restart.</p>
    </div>
    <RestartBanner />
    <p v-if="!cat && !error" class="muted">Loading the catalog from the Portal…</p>

    <!-- ===== Saved ===== -->
    <RsPanel v-if="saved" title="Done" panel-id="hwwizard.done">
      <div class="qa"><div class="qa-in">
        <img class="mascot" :src="pose('done')" alt="" />
        <div class="body">
          <p class="q">{{ saved }} is saved.</p>
          <p class="tm-hint">Restart Klipper to make it live (the banner above does it, or waits for the job to end).</p>
          <div class="acts">
            <RsButton v-if="!editing" variant="primary" @click="another">Add more hardware</RsButton>
            <RsButton :variant="editing ? 'primary' : undefined" @click="router.push('/assets/hardware')">System hardware</RsButton>
          </div>
        </div>
      </div></div>
    </RsPanel>

    <template v-else-if="cat">
      <ol class="wsteps" aria-label="Steps">
        <li v-for="(s, i) in steps" :key="s" :class="{ now: i === at, done: i < at }" :aria-current="i === at ? 'step' : undefined">
          <component :is="i < at ? 'button' : 'span'" type="button" class="in" @click="goTo(i)">
            <span class="num">{{ i < at ? '✓' : String(i + 1).padStart(2, '0') }}</span>
            <span class="txt"><span class="lab">{{ STEP_LABEL[s] }}</span><span class="det">{{ STEP_HELP[s] }}</span></span>
          </component>
        </li>
      </ol>

      <RsPanel :title="`${String(at + 1).padStart(2, '0')} · ${STEP_LABEL[step]}`" panel-id="hwwizard.step">
        <div class="qa"><div class="qa-in">
          <img class="mascot" :src="pose(STEP_POSE[step])" alt="" />
          <div class="body">
            <!-- ===== What is it ===== -->
            <template v-if="step === 'What'">
              <p class="q">{{ editing ? `What ${name} is` : 'What are you adding?' }}</p>
              <p v-if="editing && dev" class="tm-hint"><strong>{{ dev.label }}.</strong> To make it a different kind, remove it and add the new one.</p>
              <section v-for="g in editing ? [] : cat.groups" :key="g.id" class="grp">
                <h2 class="gh"><span>{{ g.label }}</span><span class="rs-rule leader" /></h2>
                <div class="tiles">
                  <button
                    v-for="x in g.devices"
                    :key="x.id"
                    type="button"
                    class="tile"
                    :class="{ on: dev?.id === x.id, off: x.status !== 'ready' && x.id !== 'board', form: x.writer === 'form' }"
                    :disabled="(x.status !== 'ready' && x.id !== 'board') || x.writer === 'form'"
                    @click="pick(x)"
                  >
                    <span class="tl">{{ x.label }}</span>
                    <span class="td">{{ x.writer === 'form' ? 'Add from System hardware' : x.status !== 'ready' && x.id !== 'board' ? 'Coming' : x.help }}</span>
                  </button>
                </div>
              </section>
              <template v-if="dev && d && !isBoard">
                <div class="tm-fld narrow">
                  <label for="hw-name">Name</label>
                  <input id="hw-name" v-model.trim="d.name" class="tm-in" maxlength="32" placeholder="e.g. chamber_fan" />
                  <span class="tm-hint">Lower-case letters, digits and _. It's the name in Klipper and in macros.</span>
                </div>
                <div class="tm-fld">
                  <label for="hw-purpose">What it's for (optional)</label>
                  <input id="hw-purpose" v-model="d.purpose" class="tm-in" maxlength="80" placeholder="e.g. Enclosure exhaust" />
                </div>
              </template>
              <template v-if="isBoard">
                <div class="tm-fld narrow">
                  <label for="hw-bname">Board name</label>
                  <input id="hw-bname" v-model.trim="board.name" class="tm-in" maxlength="16" placeholder="e.g. ebb" />
                  <span class="tm-hint">Its pins are written as name:PIN (ebb:PA1). Klipper won't start while it's unplugged.</span>
                </div>
              </template>
            </template>

            <!-- ===== Wiring ===== -->
            <template v-if="step === 'Wiring' && dev && d && !isBoard">
              <p class="q">Where is it wired?</p>
              <div v-if="asksSensorType(dev)" class="tm-fld">
                <label for="hw-sensor">What kind of switch or sensor?</label>
                <select id="hw-sensor" v-model="d.sensor_type" class="tm-sel">
                  <option v-for="[k, s] in sensorTypes" :key="k" :value="k">{{ s.label }}{{ s.recommended ? ' (recommended)' : '' }}</option>
                </select>
                <span class="tm-hint">{{ cat.sensor_types[d.sensor_type]?.note || cat.sensor_types[d.sensor_type]?.warn || 'The wizard writes the pull-up and invert for you.' }}</span>
                <span v-if="dev.purpose === 'interlock'" class="tm-hint">For an interlock, "triggered" means the door is open.</span>
              </div>
              <fieldset v-if="asksWires" class="tm-set">
                <legend>How many wires does the fan have?</legend>
                <div class="cats wires">
                  <label v-for="w in ['2', '3', '4']" :key="w" class="tm-radio" :class="{ on: d.settings.wires === w }">
                    <input v-model="d.settings.wires" type="radio" :value="w" />
                    <span><strong>{{ w }} wires</strong></span>
                  </label>
                </div>
                <span class="tm-hint">{{ WIRES_HELP[String(d.settings.wires)] }}</span>
              </fieldset>
              <div v-for="[slot, kind, required] in pinsShown(dev, d)" :key="slot" class="tm-fld">
                <label :for="`hw-pin-${slot}`">{{ slotLabel(slot) }}{{ required ? '' : ' (optional)' }} <span class="kind">{{ fan4 && slot === 'pin' ? 'Logic pin or fan header (PWM)' : cat.pin_kinds[kind]?.label }}</span></label>
                <div class="pinrow">
                  <select v-if="!typed[slot]" :id="`hw-pin-${slot}`" v-model="d.pins[slot]" class="tm-sel">
                    <option value="">{{ required ? 'Choose a pin…' : 'None' }}</option>
                    <option v-for="p in choicesFor(slot, kind)" :key="p.pin" :value="p.pin" :disabled="Object.entries(d.pins).some(([k, v]) => k !== slot && v === p.pin)">{{ pinText(p) }}</option>
                  </select>
                  <input v-else :id="`hw-pin-${slot}`" v-model.trim="d.pins[slot]" class="tm-in mono" placeholder="board:PA1" @blur="checkTyped(slot, kind)" />
                  <button type="button" class="tm-link" @click="typed[slot] = !typed[slot]; d.pins[slot] = ''">{{ typed[slot] ? 'Pick from the list' : 'Type a pin' }}</button>
                </div>
                <span class="tm-hint">{{ pinHelp(slot, kind) }}</span>
                <div v-for="(w, i) in pinWarnings(slot, kind)" :key="i" class="tm-warn">{{ w }}</div>
              </div>
              <label v-if="needsIsolation" class="tm-check">
                <input v-model="d.isolated" type="checkbox" />
                <span>An optocoupler or a divider is fitted between the sensor and the pin.</span>
              </label>
              <div v-if="wiringSettings.length" class="tm-row">
                <label v-for="s in wiringSettings" :key="s.key" class="tm-fld" :class="{ chk: s.kind === 'bool' }">
                  <template v-if="s.kind === 'bool'">
                    <span class="tm-check"><input v-model="d.settings[s.key]" type="checkbox" /> <span>{{ settingLabel(s.key) }}</span></span>
                  </template>
                  <template v-else>
                    <span class="tm-lbl">{{ settingLabel(s.key) }}</span>
                    <select v-if="s.kind === 'choice'" v-model="d.settings[s.key]" class="tm-sel"><option v-for="o in s.options" :key="o" :value="o">{{ o }}</option></select>
                    <input v-else v-model.number="d.settings[s.key]" class="tm-in" type="number" step="any" :min="s.min" :max="s.max" />
                    <span v-if="fmt(s)" class="tm-hint">{{ fmt(s) }}</span>
                  </template>
                </label>
              </div>
              <p class="tm-hint">Out of pins? Add a second board: choose "Second control board" in the first step.</p>
            </template>

            <template v-if="step === 'Wiring' && isBoard && boards">
              <p class="q">Which board, and how is it connected?</p>
              <div class="tm-fld narrow">
                <label for="hw-preset">Board</label>
                <select id="hw-preset" v-model="board.preset" class="tm-sel">
                  <option v-for="p in boards.presets" :key="p.id" :value="p.id">{{ p.label }}</option>
                </select>
                <span class="tm-hint">Pins and headers come from Klipper's own board configs. For "Other board" you type pins like {{ boards.presets.find((p) => p.id === board.preset)?.example }}, with a warning to check its pinout.</span>
              </div>
              <fieldset class="tm-set">
                <legend>Connection</legend>
                <div class="cats">
                  <label class="tm-radio" :class="{ on: board.link === 'usb' }"><input v-model="board.link" type="radio" value="usb" /><span><strong>USB</strong></span></label>
                  <label class="tm-radio" :class="{ on: board.link === 'can' }"><input v-model="board.link" type="radio" value="can" /><span><strong>CAN bus</strong></span></label>
                </div>
              </fieldset>
              <div v-if="board.link === 'usb'" class="tm-fld">
                <label for="hw-serial">USB connection</label>
                <select id="hw-serial" v-model="board.serial" class="tm-sel">
                  <option value="">Choose…</option>
                  <option v-for="p in boards.serial_ports" :key="p.path" :value="p.path" :disabled="!!p.used_by">{{ p.path.split('/').pop() }}{{ p.used_by ? ` (${p.used_by})` : '' }}</option>
                </select>
                <span class="tm-hint">{{ boards.serial_ports.length ? 'Boards plugged in now. The main board is shown as used.' : 'Nothing extra is plugged in. Plug the board in, then come back to this step.' }}</span>
              </div>
              <div v-else class="tm-fld narrow">
                <label for="hw-uuid">CAN bus UUID</label>
                <input id="hw-uuid" v-model.trim="board.canbus_uuid" class="tm-in mono" maxlength="12" placeholder="0123456789ab" />
                <span class="tm-hint">12 hex digits, from Klipper's CAN query.</span>
              </div>
            </template>

            <!-- ===== For which tools ===== -->
            <template v-if="step === 'Tools' && d">
              <p class="q">Who is it for?</p>
              <div class="cats">
                <label v-for="[v, l] in Object.entries(cat.scopes)" :key="v" class="tm-radio" :class="{ on: d.scope === v }">
                  <input v-model="d.scope" type="radio" :value="v" @change="d.scope_values = []" />
                  <span><strong>{{ l }}</strong></span>
                </label>
              </div>
              <div v-if="d.scope === 'category'" class="chips">
                <label v-for="[v, l] in CATS" :key="v" class="chip" :class="{ on: d.scope_values.includes(v) }">
                  <input type="checkbox" :checked="d.scope_values.includes(v)" @change="toggle(d.scope_values, v, ($event.target as HTMLInputElement).checked)" />{{ l }}
                </label>
              </div>
              <div v-if="d.scope === 'tools'" class="chips">
                <label v-for="t in tm.tools" :key="t.name" class="chip" :class="{ on: d.scope_values.includes(t.name) }">
                  <input type="checkbox" :checked="d.scope_values.includes(t.name)" @change="toggle(d.scope_values, t.name, ($event.target as HTMLInputElement).checked)" />{{ t.name }}
                </label>
              </div>
              <p class="tm-hint">Whole machine: always available. Otherwise its ON macro refuses unless a matching tool is mounted, and a tool swap turns it off.</p>
            </template>

            <!-- ===== Follows ===== -->
            <template v-if="step === 'Follows' && dev && d">
              <p class="q">What turns it on and off?</p>
              <div class="tm-list">
                <label v-for="f in dev.follows" :key="f" class="tm-radio" :class="{ on: d.follows === f, dim: !built.includes(f) }">
                  <input v-model="d.follows" type="radio" :value="f" :disabled="!built.includes(f)" />
                  <span><strong>{{ cat.follows[f] }}</strong><span v-if="!built.includes(f)" class="tm-hint"> · comes with job hooks</span></span>
                </label>
              </div>
              <div v-if="behaviourSettings.length" class="tm-row">
                <label v-for="s in behaviourSettings.filter((s) => s.key !== 'gcode' || d!.follows === 'gcode')" :key="s.key" class="tm-fld" :class="{ chk: s.kind === 'bool' }">
                  <template v-if="s.kind === 'bool'">
                    <span class="tm-check"><input v-model="d.settings[s.key]" type="checkbox" /> <span>{{ settingLabel(s.key) }}</span></span>
                  </template>
                  <template v-else>
                    <span class="tm-lbl">{{ settingLabel(s.key) }}</span>
                    <select v-if="s.kind === 'choice'" v-model="d.settings[s.key]" class="tm-sel"><option v-for="o in s.options" :key="o" :value="o">{{ o }}</option></select>
                    <input v-else v-model.number="d.settings[s.key]" class="tm-in" type="number" step="any" :min="s.min" :max="s.max" />
                    <span v-if="fmt(s)" class="tm-hint">{{ fmt(s) }}</span>
                  </template>
                </label>
              </div>
              <p v-if="dev.id === 'interlock'" class="tm-hint">Opening it pauses a running job. "Must be closed to start" takes effect with the start-check macro change, after review.</p>
            </template>

            <!-- ===== Shows ===== -->
            <template v-if="step === 'Shows' && dev && d">
              <p class="q">Where should it show?</p>
              <div class="tm-list">
                <label v-for="e in dev.expose_allowed ?? dev.expose" :key="e" class="tm-check">
                  <input type="checkbox" :checked="d.expose.includes(e)" :disabled="e === 'hooks'" @change="toggle(d.expose, e, ($event.target as HTMLInputElement).checked)" />
                  <span>{{ cat.expose[e] }}{{ e === 'hooks' ? ' (comes with job hooks)' : '' }}</span>
                </label>
                <p v-if="!(dev.expose_allowed ?? dev.expose).length" class="tm-hint">Klipper runs this by itself: nothing to show or switch.</p>
              </div>
              <p v-if="dev.live" class="tm-hint">It's live-dangerous, so it sits behind the padlock on Control and is always switched off at the end of a job, on cancel and on a tool swap.</p>
              <div class="tm-fld">
                <label for="hw-notes">Notes (optional)</label>
                <textarea id="hw-notes" v-model="d.notes" class="tm-ta" maxlength="1000" placeholder="Wiring, supplier, settings that worked…" />
              </div>
            </template>

            <!-- ===== Check ===== -->
            <template v-if="step === 'Check'">
              <p class="q">Here's what gets written.</p>
              <p v-if="checking" class="tm-hint">Checking it against your Klipper config…</p>
              <template v-if="preview">
                <div v-for="(w, i) in preview.warnings" :key="i" class="tm-warn">{{ w }}</div>
                <pre class="tm-pre">{{ preview.text }}</pre>
                <p class="tm-ok">Ready. Save writes it to custom_tools.cfg; it's live after the next Klipper restart.</p>
              </template>
            </template>
          </div>
        </div></div>
      </RsPanel>

      <p v-if="error" class="tm-err" role="alert">{{ error }}</p>
      <footer class="bar">
        <RsButton v-if="at > 0" @click="back">Back</RsButton>
        <RsButton variant="primary" :disabled="!dev || (step === 'Check' && (!preview || checking)) || saving" @click="next">
          {{ step === 'Check' ? (saving ? 'Saving…' : 'Save') : 'Next' }}
        </RsButton>
        <span class="tm-hint">Step {{ at + 1 }} of {{ steps.length }}</span>
        <RsButton class="cancel" variant="quiet" @click="router.push('/assets/hardware')">Cancel</RsButton>
      </footer>
    </template>
    <p v-else-if="error" class="tm-err">{{ error }}</p>
  </div>
</template>

